package com.rikkeibank.account.service; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; import com.rikkeibank.account.dto.AccountOperationRequest; import com.rikkeibank.account.model.BankAccount; import com.rikkeibank.account.repository.*; import java.math.BigDecimal; import java.util.Optional; import org.junit.jupiter.api.Test; import org.springframework.web.server.ResponseStatusException;
class BankAccountServiceTest{@Test void debitRejectsInsufficientBalance(){BankAccountRepository r=mock(BankAccountRepository.class);AccountTypeRepository t=mock(AccountTypeRepository.class);AccountOperationRepository o=mock(AccountOperationRepository.class);BankAccount a=new BankAccount();a.setId(1L);a.setAccountNumber("1");a.setOwnerUsername("customer01");a.setActive(true);a.setBalance(new BigDecimal("10"));when(r.findByIdForUpdate(1L)).thenReturn(Optional.of(a));BankAccountService s=new BankAccountService(r,t,o);assertThrows(ResponseStatusException.class,()->s.debit(new AccountOperationRequest(1L,"customer01",new BigDecimal("20"),"op1")));}}
